-- Sälj flyttad till databasen (claude/teknik-status-saljlista.md, punkt 1)
-- data/sell.json är idag en delad, publik fil utan inloggningskoppling -
-- samma mönster som fotobehörighetshålet (PR 4.5) hade. RLS-mönstret följer
-- manual_books/bc_photos: en biblioteksmedlem kan läsa och ändra sitt eget
-- bibliotekets säljkandidater, ingen annan kan se dem.
--
-- book_id (ny, finns inte i sell.json) löser samtidigt ett känt litet fel
-- (flödesrapporten 2026-10-26, punkt 4.3): "Står i:"-raden matchade tidigare
-- på exakt titelsträng vid varje visning, och tappades tyst bort så fort en
-- titel rättades i katalogen. Nu kopplas varje säljpost till boken en gång,
-- vid migreringen - kopplingen följer sedan med även om titeln ändras.

create table public.sell_items (
  id bigint generated by default as identity primary key,
  library_id uuid not null references public.libraries(id) on delete cascade,
  book_id bigint references public.manual_books(id) on delete set null,
  title text not null,
  match_title text,
  price text,
  heat text,
  why text,
  url text,
  checked boolean not null default false,
  low integer,
  created_at timestamptz not null default now()
);

create table public.sell_meta (
  library_id uuid primary key references public.libraries(id) on delete cascade,
  note text,
  updated_date date,
  summary jsonb
);

alter table public.sell_items enable row level security;
alter table public.sell_meta enable row level security;

create policy "sell_items read" on public.sell_items for select
  using (public.is_library_member(library_id));
create policy "sell_items insert" on public.sell_items for insert
  with check (public.is_library_member(library_id));
create policy "sell_items update" on public.sell_items for update
  using (public.is_library_member(library_id)) with check (public.is_library_member(library_id));
create policy "sell_items delete" on public.sell_items for delete
  using (public.is_library_member(library_id));

create policy "sell_meta read" on public.sell_meta for select
  using (public.is_library_member(library_id));
create policy "sell_meta insert" on public.sell_meta for insert
  with check (public.is_library_member(library_id));
create policy "sell_meta update" on public.sell_meta for update
  using (public.is_library_member(library_id)) with check (public.is_library_member(library_id));
create policy "sell_meta delete" on public.sell_meta for delete
  using (public.is_library_member(library_id));

