insert into public.sell_items (library_id, book_id, title, match_title, price, heat, why, url, checked, low)
select
  lib.id,
  coalesce(
    (select mb.id from public.manual_books mb where mb.library_id=lib.id and mb.title=i.match_title limit 1),
    (select mb.id from public.manual_books mb where mb.library_id=lib.id and mb.title like i.match_title || '%' order by mb.id limit 1)
  ),
  i.title, i.match_title, i.price, i.heat, i.why, i.url, i.checked, i.low
from items i, lib;

